Time: O(n)  |  Space: O(1)
Finds a pair of numbers that sum to a target in a sorted array.
def pair_with_sum(arr, target):
left, right = 0, len(arr) - 1
while left < right:
total = arr[left] + arr[right]
if total == target:
return (arr[left], arr[right])
elif total < target:
left += 1
else:
right -= 1
return None
print(pair_with_sum([1, 2, 3, 4, 6, 8, 11], 10))
# Output: (2, 8)

Time: O(1) insert at head, O(n) traverse  |  Space: O(n)
A minimal singly linked list with head insertion and printing.
class Node:
def __init__(self, data):
self.data = data
self.next = None
class LinkedList:
def __init__(self):
self.head = None
def insert_head(self, data):
node = Node(data)
node.next = self.head
self.head = node
def print_list(self):
cur = self.head
while cur:
print(cur.data, end=" -> ")
cur = cur.next
print("None")
ll = LinkedList()
for val in [3, 2, 1]:
ll.insert_head(val)
ll.print_list()
# Output: 1 -> 2 -> 3 -> None

Time: O(n)  |  Space: O(1)
Uses slow/fast pointers to detect a cycle in a linked list.
def has_cycle(head):
slow = fast = head
while fast and fast.next:
slow = slow.next
fast = fast.next.next
if slow is fast:
return True
return False

Time: O(n + m)  |  Space: O(1) extra
Merges two sorted linked lists into a single sorted list.
def merge_sorted(l1, l2):
dummy = Node(0)
tail = dummy
while l1 and l2:
if l1.data <= l2.data:
tail.next, l1 = l1, l1.next
else:
tail.next, l2 = l2, l2.next
tail = tail.next
tail.next = l1 or l2
return dummy.next

Time: O(1) with tail pointer  |  Space: O(n)
A doubly linked list node supports traversal in both directions.
class DNode:
def __init__(self, data):
self.data = data
self.prev = None
self.next = None
class DoublyLinkedList:
def __init__(self):
self.head = self.tail = None
def append(self, data):
node = DNode(data)
if not self.head:
self.head = self.tail = node
return
node.prev = self.tail
self.tail.next = node
self.tail = node

Time: O(1) push/pop  |  Space: O(n)
The simplest stack implementation using a dynamic array.
class Stack:
def __init__(self):
self._items = []
def push(self, item):
self._items.append(item)
def pop(self):
return self._items.pop() if self._items else None
def peek(self):
return self._items[-1] if self._items else None
def is_empty(self):
return len(self._items) == 0
s = Stack()
s.push(1); s.push(2); s.push(3)
print(s.pop())    # 3
print(s.peek())   # 2

Time: O(n)  |  Space: O(n)
Classic stack application: validates matching brackets.
def is_balanced(expr):
pairs = {")": "(", "]": "[", "}": "{"}
stack = []
for ch in expr:
if ch in "([{":
stack.append(ch)
elif ch in ")]}":
if not stack or stack.pop() != pairs[ch]:
return False
return not stack
print(is_balanced("{[()()]}"))  # True
print(is_balanced("{[(])}"))    # False

Time: O(n)  |  Space: O(n)
Evaluates a postfix (Reverse Polish Notation) expression using a stack.
def eval_postfix(tokens):
stack = []
ops = {"+": lambda a, b: a + b, "-": lambda a, b: a - b,
"*": lambda a, b: a * b, "/": lambda a, b: a / b}
for tok in tokens:
if tok in ops:
b, a = stack.pop(), stack.pop()
stack.append(ops[tok](a, b))
else:
stack.append(float(tok))
return stack[0]
print(eval_postfix(["2", "3", "4", "*", "+"]))
# Output: 14.0

Time: O(1) enqueue/dequeue  |  Space: O(n)
Using deque avoids the O(n) pop(0) cost of a plain list.
from collections import deque
class Queue:
def __init__(self):
self._items = deque()
def enqueue(self, item):
self._items.append(item)
def dequeue(self):
return self._items.popleft() if self._items else None
q = Queue()
q.enqueue(1); q.enqueue(2); q.enqueue(3)
print(q.dequeue())  # 1

Time: O(1) enqueue/dequeue  |  Space: O(k)
A ring-buffer style queue with a fixed maximum size.
class CircularQueue:
def __init__(self, capacity):
self.cap = capacity
self.data = [None] * capacity
self.head = self.count = 0
def enqueue(self, val):
if self.count == self.cap:
raise OverflowError("Queue is full")
tail = (self.head + self.count) % self.cap
self.data[tail] = val
self.count += 1
def dequeue(self):
if self.count == 0:
raise IndexError("Queue is empty")
val = self.data[self.head]
self.head = (self.head + 1) % self.cap
self.count -= 1
return val

Time: O(1) all ops  |  Space: O(n)
Tracks the minimum element alongside a normal stack using an auxiliary stack.
class MinStack:
def __init__(self):
self.stack = []
self.min_stack = []
def push(self, val):
self.stack.append(val)
m = val if not self.min_stack else min(val, self.min_stack[-1])
self.min_stack.append(m)
def pop(self):
self.min_stack.pop()
return self.stack.pop()
def get_min(self):
return self.min_stack[-1]

