Time: O(h), h = tree height  |  Space: O(h)
A BST maintains the invariant: left < node < right.
class TreeNode:
def __init__(self, val):
self.val = val
self.left = None
self.right = None
def insert(root, val):
if root is None:
return TreeNode(val)
if val < root.val:
root.left = insert(root.left, val)
else:
root.right = insert(root.right, val)
return root
def search(root, val):
if root is None or root.val == val:
return root
if val < root.val:
return search(root.left, val)
return search(root.right, val)

Time: O(n)  |  Space: O(n)
Traverses the tree level by level using a queue.
from collections import deque
def level_order(root):
if not root:
return []
result, queue = [], deque([root])
while queue:
level = []
for _ in range(len(queue)):
node = queue.popleft()
level.append(node.val)
if node.left:
queue.append(node.left)
if node.right:
queue.append(node.right)
result.append(level)
return result

Time: O(n)  |  Space: O(h)
Recursively computes the maximum depth of the tree.
def height(root):
if root is None:
return 0
return 1 + max(height(root.left), height(root.right))

Time: O(n)  |  Space: O(h)
Checks the BST property using a valid (min, max) range per node.
def is_valid_bst(root, low=float("-inf"), high=float("inf")):
if root is None:
return True
if not (low < root.val < high):
return False
return (is_valid_bst(root.left, low, root.val) and
is_valid_bst(root.right, root.val, high))

Time: O(h)  |  Space: O(1)
Uses BST ordering to find the LCA without extra storage.
def lca(root, p, q):
while root:
if p < root.val and q < root.val:
root = root.left
elif p > root.val and q > root.val:
root = root.right
else:
return root
return None

Time: O(V + E)  |  Space: O(V)
Explores the graph level by level, useful for shortest paths in unweighted graphs.
from collections import deque
def bfs(graph, start):
visited = {start}
order = []
queue = deque([start])
while queue:
node = queue.popleft()
order.append(node)
for neighbor in graph[node]:
if neighbor not in visited:
visited.add(neighbor)
queue.append(neighbor)
return order

Time: O(V + E)  |  Space: O(V)
Explores as far as possible along each branch before backtracking.
def dfs(graph, node, visited=None, order=None):
if visited is None:
visited, order = set(), []
visited.add(node)
order.append(node)
for neighbor in graph[node]:
if neighbor not in visited:
dfs(graph, neighbor, visited, order)
return order

Time: O(V + E)  |  Space: O(V)
Uses a recursion-stack marker in addition to visited to detect back edges.
def has_cycle_directed(graph, nodes):
visited, in_stack = set(), set()
def dfs(node):
visited.add(node)
in_stack.add(node)
for neighbor in graph[node]:
if neighbor not in visited:
if dfs(neighbor):
return True
elif neighbor in in_stack:
return True
in_stack.remove(node)
return False
return any(dfs(n) for n in nodes if n not in visited)

Time: O(V + E)  |  Space: O(V)
Orders nodes of a DAG so every edge points forward, using in-degree counting.
from collections import deque, defaultdict
def topo_sort(graph, nodes):
in_degree = {n: 0 for n in nodes}
for u in graph:
for v in graph[u]:
in_degree[v] += 1
queue = deque([n for n in nodes if in_degree[n] == 0])
order = []
while queue:
node = queue.popleft()
order.append(node)
for neighbor in graph[node]:
in_degree[neighbor] -= 1
if in_degree[neighbor] == 0:
queue.append(neighbor)
return order if len(order) == len(nodes) else []  # [] means a cycle exists

Time: O((V + E) log V)  |  Space: O(V)
Finds shortest paths from a source in a graph with non-negative weights.
import heapq
def dijkstra(graph, start):
# graph[node] = list of (neighbor, weight)
dist = {start: 0}
heap = [(0, start)]
while heap:
d, node = heapq.heappop(heap)
if d > dist.get(node, float("inf")):
continue
for neighbor, weight in graph[node]:
nd = d + weight
if nd < dist.get(neighbor, float("inf")):
dist[neighbor] = nd
heapq.heappush(heap, (nd, neighbor))
return dist

Time: O(V + E)  |  Space: O(V)
Counts connected components in an undirected graph via repeated DFS.
def count_components(graph, nodes):
visited = set()
def dfs(node):
visited.add(node)
for neighbor in graph[node]:
if neighbor not in visited:
dfs(neighbor)
count = 0
for node in nodes:
if node not in visited:
dfs(node)
count += 1
return count

Time: O(n)  |  Space: O(n)
Top-down DP: caches results to avoid recomputation.
from functools import lru_cache
@lru_cache(maxsize=None)
def fib_memo(n):
if n <= 1:
return n
return fib_memo(n - 1) + fib_memo(n - 2)
print(fib_memo(40))  # instant, vs. minutes for naive recursion

Time: O(n)  |  Space: O(1)
Iterative DP using two rolling variables instead of an array.
def fib_tab(n):
if n <= 1:
return n
a, b = 0, 1
for _ in range(2, n + 1):
a, b = b, a + b
return b
print(fib_tab(30))  # 832040

Time: O(n * W)  |  Space: O(n * W)
Selects items to maximize value without exceeding a weight capacity.
def knapsack(weights, values, capacity):
n = len(weights)
dp = [[0] * (capacity + 1) for _ in range(n + 1)]
for i in range(1, n + 1):
for w in range(capacity + 1):
dp[i][w] = dp[i - 1][w]
if weights[i - 1] <= w:
dp[i][w] = max(dp[i][w],
dp[i - 1][w - weights[i - 1]] + values[i - 1])
return dp[n][capacity]
print(knapsack([1, 3, 4, 5], [1, 4, 5, 7], 7))  # 9

Time: O(m * n)  |  Space: O(m * n)
Finds the length of the longest subsequence common to two strings.
def lcs(a, b):
m, n = len(a), len(b)
dp = [[0] * (n + 1) for _ in range(m + 1)]
for i in range(1, m + 1):
for j in range(1, n + 1):
if a[i - 1] == b[j - 1]:
dp[i][j] = dp[i - 1][j - 1] + 1
else:
dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])
return dp[m][n]
print(lcs("abcde", "ace"))  # 3

Time: O(n log n)  |  Space: O(n)
Uses binary search on a patience-sorting pile array for the O(n log n) version.
import bisect
def length_of_lis(nums):
piles = []
for num in nums:
idx = bisect.bisect_left(piles, num)
if idx == len(piles):
piles.append(num)
else:
piles[idx] = num
return len(piles)
print(length_of_lis([10, 9, 2, 5, 3, 7, 101, 18]))  # 4

Time: O(amount * len(coins))  |  Space: O(amount)
Finds the fewest coins needed to make a given amount.
def coin_change(coins, amount):
dp = [0] + [float("inf")] * amount
for a in range(1, amount + 1):
for c in coins:
if c <= a:
dp[a] = min(dp[a], dp[a - c] + 1)
return dp[amount] if dp[amount] != float("inf") else -1
print(coin_change([1, 2, 5], 11))  # 3  (5 + 5 + 1)

Time: O(m * n)  |  Space: O(m * n)
Minimum insert/delete/replace operations to convert one string into another.
def edit_distance(a, b):
m, n = len(a), len(b)
dp = [[0] * (n + 1) for _ in range(m + 1)]
for i in range(m + 1):
dp[i][0] = i
for j in range(n + 1):
dp[0][j] = j
for i in range(1, m + 1):
for j in range(1, n + 1):
if a[i - 1] == b[j - 1]:
dp[i][j] = dp[i - 1][j - 1]
else:
dp[i][j] = 1 + min(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1])
return dp[m][n]
print(edit_distance("horse", "ros"))  # 3

Time: O(k), k = word length  |  Space: O(alphabet * n * k)
Efficient prefix-based string storage and lookup, used in autocomplete.
class TrieNode:
def __init__(self):
self.children = {}
self.is_end = False
class Trie:
def __init__(self):
self.root = TrieNode()
def insert(self, word):
node = self.root
for ch in word:
node = node.children.setdefault(ch, TrieNode())
node.is_end = True
def search(self, word):
node = self.root
for ch in word:
if ch not in node.children:
return False
node = node.children[ch]
return node.is_end
def starts_with(self, prefix):
node = self.root
for ch in prefix:
if ch not in node.children:
return False
node = node.children[ch]
return True
trie = Trie()
trie.insert("apple")
print(trie.search("apple"))       # True
print(trie.search("app"))         # False
print(trie.starts_with("app"))    # True

Time: O(alpha(n)) amortized per op  |  Space: O(n)
Tracks connected components efficiently; used in Kruskal's MST and cycle detection.
class UnionFind:
def __init__(self, n):
self.parent = list(range(n))
self.rank = [0] * n
def find(self, x):
if self.parent[x] != x:
self.parent[x] = self.find(self.parent[x])  # path compression
return self.parent[x]
def union(self, x, y):
rx, ry = self.find(x), self.find(y)
if rx == ry:
return False
if self.rank[rx] < self.rank[ry]:
rx, ry = ry, rx
self.parent[ry] = rx
if self.rank[rx] == self.rank[ry]:
self.rank[rx] += 1
return True
uf = UnionFind(5)
uf.union(0, 1)
uf.union(1, 2)
print(uf.find(0) == uf.find(2))  # True
print(uf.find(0) == uf.find(3))  # False
